-- ============================================================
--  الاستراتيجيات الوطنية — 52 استراتيجية من عرض الإدارة
--  آمن للتكرار: يحذف بذرة العرض القديمة ثم يُدرج، ولا يدهس
--  صفاً عُدّل لاحقاً (on conflict do nothing).
-- ============================================================
delete from public.perf_items
 where section = 'natstrat' and data->>'demo' = 'true';

on conflict (section, id) do nothing;

select data->>'stage' as "حالة الاعتماد", count(*)
  from public.perf_items where section='natstrat' group by 1 order by 1 desc;
